    private static MainWindowViewModel Scene5D(string layout="Grid",string? only=null)
    {
        var vm=GridFirstVm();if(layout=="Canvas"){vm.NewFormLayoutChoice=MainWindowViewModel.NewFormCanvasChoice;vm.NewProjectEditorCommand!.Execute(null);}
        vm.DesignWidth=1000;vm.DesignHeight=800;vm.SurfaceGridRowDefinitions="*,*,*";vm.SurfaceGridColumnDefinitions="*,*";
        var types=only is null?Phase5DTypes:new[]{only};
        for(var i=0;i<types.Length;i++){
            var c=vm.CreateControl(types[i],20+460*(i%2),20+220*(i/2));c.Name="Phase5D_"+c.Type;c.Width=380;c.Height=170;c.WidthMode=c.HeightMode="Fixed";c.GridRow=i/2;c.GridColumn=i%2;
            if(c.Type=="ContentControl"){SetUniversal2(c,"Padding","4,6,8,10");var child=vm.CreateControl("TextBox",0,0,c.Id);child.Name="ContentText";child.Text="Nested & content";child.Width=200;child.Height=40;child.WidthMode=child.HeightMode="Fixed";}
            else{var kind=CollectionItemsContract.ItemKind(c.Type,"Items");StandardItemsProperties.Write(c,CollectionItemsContract.StorageKey("Items"),new CollectionItemsContract{Items=Enumerable.Range(0,3).Select(n=>new StandardMenuItem{Kind=kind,Name=c.Type+"Item"+n,Text="Item "+n}).ToList()});if(c.Type!="ItemsControl")StandardItemsProperties.Write(c,"SelectedIndex",1);}
        }
        return vm;
    }
    private static Control Native5D(Control root,DesignControlModel model)=>root.GetVisualDescendants().OfType<Control>().Single(c=>c.Name==model.Name&&c.GetType().Name==(model.Name.StartsWith("Phase5D_")?model.Name[8..]:model.Type));
    private static void AssertNative5D(Control control,string type)
    {
        RequireCapability(control.GetType().Name==type&&control.GetVisualRoot()!=null&&control.Bounds.Width>0&&control.Bounds.Height>0,"Native geometry missing "+type+" "+control.Bounds);
        if(control is ItemsControl items){RequireCapability(items.Items.Count==3,"Items lost");var expected=type=="TabStrip"?typeof(TabStripItem):typeof(ContentControl);RequireCapability(items.Items.Cast<Control>().All(c=>c.GetType()==expected),"Wrong native item type");RequireCapability(items.Items.Cast<ContentControl>().Select(c=>(string)c.Content!).SequenceEqual(new[]{"Item 0","Item 1","Item 2"}),"Content/order lost");if(items is SelectingItemsControl selecting)RequireCapability(selecting.SelectedIndex==1,"SelectedIndex lost");
            var visible=items is Carousel?items.Items.Cast<Control>().Skip(1).Take(1):items.Items.Cast<Control>();
            RequireCapability(visible.All(c=>c.GetVisualRoot()is not null&&c.Bounds.Width>0&&c.Bounds.Height>0&&c.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text==((ContentControl)c).Content as string)),"Item content is not realized in native visual tree: "+type);}
        else RequireCapability(control.GetVisualDescendants().OfType<TextBox>().Any(t=>t.Text=="Nested & content"),"Single Content lost");
    }
