    private static int GenerateUniversal5DProjects(){var folder=Environment.GetEnvironmentVariable("UNIVERSAL5D_EXPORT_DIR")!;RequireCapability(!Directory.Exists(folder),"Fresh export required");foreach(var layout in new[]{"Grid","Canvas"}){var vm=Scene5D(layout);var mask=vm.CreateControl("MaskedTextBox",20,500);mask.Name="Mask5D";mask.Text="123456";mask.GridRow=2;mask.Width=320;mask.Height=50;mask.WidthMode=mask.HeightMode="Fixed";foreach(var kv in new[]{("Mask","000-000"),("PromptChar","#"),("SelectionStart","1"),("SelectionEnd","3")})SetUniversal2(mask,kv.Item1,kv.Item2);Pump(vm.ExportCurrentResultToProjectAsync(Path.Combine(folder,layout)));}return 0;}
    private static int RunUniversal5DAudit(){var folder=Environment.GetEnvironmentVariable("UNIVERSAL5D_OUTPUT_DIR")!;var vm=GridFirstVm();var verified=Environment.GetEnvironmentVariable("UNIVERSAL5D_RUNTIME_VERIFIED")=="1"?Phase5ATypes.Concat(Phase5BTypes).Concat(Phase5CTypes).Concat(Phase5DTypes).Append("TabStripItem").ToHashSet():null;MetadataCoverageReport.Write(vm.Registry,folder,verified);StandardLibraryCoverageReport.Write(vm.Registry,folder,verified);Write5DPropertyInventory(vm.Registry,folder);Dispose5AProfileVm(vm);return 0;}
